CREATE EXTENSION IF NOT EXISTS pgcrypto;
DO $$ BEGIN CREATE TYPE user_role AS ENUM ('SUPER_ADMIN','ADMIN','MENTOR','INTERN'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
CREATE TABLE IF NOT EXISTS users(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),email text UNIQUE NOT NULL,password_hash text NOT NULL,role user_role NOT NULL DEFAULT 'INTERN',status text NOT NULL DEFAULT 'REGISTERED',is_active boolean NOT NULL DEFAULT false,created_at timestamptz DEFAULT now(),updated_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS colleges(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name text UNIQUE NOT NULL,university text,active boolean DEFAULT true,created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS intern_profiles(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid UNIQUE REFERENCES users(id) ON DELETE CASCADE,full_name text NOT NULL,mobile text,dob date,address text,photo_url text,college_id uuid REFERENCES colleges(id),university text,program text,branch text,year_semester text,roll_number text,preferred_domains jsonb DEFAULT '[]',preferred_batch text,mode_preference text,skills_tools text,resume_portfolio_url text,consent_genuine boolean DEFAULT false,consent_storage boolean DEFAULT false,final_domain_id uuid,created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS college_coordinators(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),college_id uuid REFERENCES colleges(id),name text,designation text,email text,phone text);
CREATE TABLE IF NOT EXISTS college_proofs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),intern_id uuid REFERENCES intern_profiles(id) ON DELETE CASCADE,proof_type text NOT NULL,issuing_authority text NOT NULL,reference_number text NOT NULL,issue_date date NOT NULL,approved_from date,approved_to date,coordinator_id uuid REFERENCES college_coordinators(id),file_path text,file_hash text,status text DEFAULT 'UPLOADED',version int DEFAULT 1,reason text,batch_order_id uuid,created_at timestamptz DEFAULT now());
CREATE UNIQUE INDEX IF NOT EXISTS uq_proof_ref ON college_proofs(reference_number) WHERE status <> 'REJECTED';
CREATE TABLE IF NOT EXISTS proof_verifications(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),proof_id uuid REFERENCES college_proofs(id),actor_id uuid REFERENCES users(id),outcome text NOT NULL,checklist jsonb DEFAULT '{}',reason text,created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS domains(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name text UNIQUE NOT NULL,code text UNIQUE NOT NULL,category text,description text,active boolean DEFAULT true,default_capacity int DEFAULT 25,allowed_deliverables jsonb DEFAULT '[]');
CREATE TABLE IF NOT EXISTS subdomains(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),domain_id uuid REFERENCES domains(id) ON DELETE CASCADE,name text NOT NULL,code text NOT NULL,active boolean DEFAULT true);
CREATE TABLE IF NOT EXISTS rubrics(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),domain_id uuid REFERENCES domains(id),name text NOT NULL,active boolean DEFAULT true);
CREATE TABLE IF NOT EXISTS rubric_criteria(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),rubric_id uuid REFERENCES rubrics(id) ON DELETE CASCADE,name text NOT NULL,max_marks numeric NOT NULL,weight numeric NOT NULL,kind text DEFAULT 'DOMAIN');
CREATE TABLE IF NOT EXISTS batches(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),college_id uuid REFERENCES colleges(id),name text NOT NULL,code text UNIQUE NOT NULL,start_date date NOT NULL,end_date date NOT NULL,working_days jsonb DEFAULT '[1,2,3,4,5]',mode text DEFAULT 'ONSITE',task_release_rule jsonb DEFAULT '{}',review_rule jsonb DEFAULT '{}',min_attendance numeric DEFAULT 75,status text DEFAULT 'DRAFT',created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS batch_domains(batch_id uuid REFERENCES batches(id) ON DELETE CASCADE,domain_id uuid REFERENCES domains(id),capacity int,PRIMARY KEY(batch_id,domain_id));
CREATE TABLE IF NOT EXISTS batch_allocations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),batch_id uuid REFERENCES batches(id),intern_id uuid REFERENCES intern_profiles(id),status text DEFAULT 'BATCH_ASSIGNED',intern_start date,intern_end date,date_mismatch boolean DEFAULT false,override_reason text,UNIQUE(batch_id,intern_id));
CREATE TABLE IF NOT EXISTS batch_allotment_orders(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),batch_id uuid REFERENCES batches(id),reference_number text UNIQUE NOT NULL,issue_date date,issuing_authority text,file_path text,file_hash text,approved_from date,approved_to date,created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS allotment_verifications(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),allocation_id uuid REFERENCES batch_allocations(id),actor_id uuid REFERENCES users(id),status text NOT NULL,reason text,created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS offer_letter_templates(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name text,version int DEFAULT 1,body text NOT NULL,signatory text,active boolean DEFAULT true);
CREATE TABLE IF NOT EXISTS offer_letters(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),allocation_id uuid REFERENCES batch_allocations(id),student_name_snapshot text,college_snapshot text,batch_snapshot text,from_date date,to_date date,duration_text text,issue_at timestamptz,template_id uuid REFERENCES offer_letter_templates(id),template_version int,reference_number text UNIQUE,status text DEFAULT 'DRAFT',issued_by uuid REFERENCES users(id),reason text,created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS offer_letter_versions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),offer_letter_id uuid REFERENCES offer_letters(id),version int NOT NULL,snapshot jsonb NOT NULL,reason text,created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS mentors(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid UNIQUE REFERENCES users(id),full_name text NOT NULL,expertise jsonb DEFAULT '[]',max_groups int DEFAULT 5,max_interns int DEFAULT 30,active boolean DEFAULT true);
CREATE TABLE IF NOT EXISTS question_bank(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),domain_id uuid REFERENCES domains(id),topic text,difficulty text,type text NOT NULL,question text NOT NULL,options jsonb,correct_answer jsonb,marking_guide text,marks numeric DEFAULT 1,explanation text,status text DEFAULT 'DRAFT',source text DEFAULT 'MANUAL');
CREATE TABLE IF NOT EXISTS assessments(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),batch_id uuid REFERENCES batches(id),name text NOT NULL,window_start timestamptz,window_end timestamptz,duration_minutes int,attempt_count int DEFAULT 1,randomize boolean DEFAULT true,status text DEFAULT 'DRAFT');
CREATE TABLE IF NOT EXISTS assessment_sections(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),assessment_id uuid REFERENCES assessments(id) ON DELETE CASCADE,domain_id uuid REFERENCES domains(id),name text,pass_score numeric,question_ids jsonb DEFAULT '[]');
CREATE TABLE IF NOT EXISTS assessment_attempts(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),assessment_id uuid REFERENCES assessments(id),intern_id uuid REFERENCES intern_profiles(id),status text DEFAULT 'IN_PROGRESS',started_at timestamptz DEFAULT now(),submitted_at timestamptz,total_score numeric DEFAULT 0,tab_switches int DEFAULT 0);
CREATE TABLE IF NOT EXISTS assessment_answers(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),attempt_id uuid REFERENCES assessment_attempts(id) ON DELETE CASCADE,question_id uuid REFERENCES question_bank(id),answer jsonb,auto_score numeric,manual_score numeric,evaluator_id uuid REFERENCES users(id),feedback text,status text DEFAULT 'SUBMITTED');
CREATE TABLE IF NOT EXISTS domain_decisions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),intern_id uuid REFERENCES intern_profiles(id),batch_id uuid REFERENCES batches(id),preferences jsonb,recommendations jsonb,confirmed_domain_id uuid REFERENCES domains(id),confirmed_by uuid REFERENCES users(id),created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS groups(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),batch_id uuid REFERENCES batches(id),name text NOT NULL,type text DEFAULT 'SINGLE_DOMAIN',status text DEFAULT 'SYSTEM_DRAFT',lead_mentor_id uuid REFERENCES mentors(id),created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS group_members(group_id uuid REFERENCES groups(id) ON DELETE CASCADE,intern_id uuid REFERENCES intern_profiles(id),domain_id uuid REFERENCES domains(id),active boolean DEFAULT true,PRIMARY KEY(group_id,intern_id));
CREATE TABLE IF NOT EXISTS mentor_assignments(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),mentor_id uuid REFERENCES mentors(id),group_id uuid REFERENCES groups(id),domain_id uuid REFERENCES domains(id),is_lead boolean DEFAULT false,active boolean DEFAULT true,assigned_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS projects(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),title text NOT NULL,description text,domain_ids jsonb DEFAULT '[]',milestones jsonb DEFAULT '[]',tools_methods text,resources text,duration_suitability text,deliverable_types jsonb DEFAULT '[]',status text DEFAULT 'ACTIVE');
CREATE TABLE IF NOT EXISTS project_assignments(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),project_id uuid REFERENCES projects(id),group_id uuid REFERENCES groups(id),assigned_by uuid REFERENCES users(id),status text DEFAULT 'ASSIGNED',UNIQUE(project_id,group_id));
CREATE TABLE IF NOT EXISTS face_enrollments(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),intern_id uuid REFERENCES intern_profiles(id),template_ref text,raw_image_path text,status text DEFAULT 'NOT_ENROLLED',consent_at timestamptz,quality_score numeric,decision_reason text,approved_by uuid REFERENCES users(id),approved_at timestamptz,created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS attendance_events(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),intern_id uuid REFERENCES intern_profiles(id),batch_id uuid REFERENCES batches(id),event_type text NOT NULL,event_time timestamptz DEFAULT now(),match_score numeric,liveness_pass boolean,evidence_ref text,status text DEFAULT 'RECORDED');
CREATE TABLE IF NOT EXISTS attendance_daily(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),intern_id uuid REFERENCES intern_profiles(id),batch_id uuid REFERENCES batches(id),day date NOT NULL,check_in timestamptz,check_out timestamptz,working_minutes int DEFAULT 0,status text DEFAULT 'ABSENT',UNIQUE(intern_id,day));
CREATE TABLE IF NOT EXISTS attendance_exceptions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),intern_id uuid REFERENCES intern_profiles(id),day date,kind text,reason text,status text DEFAULT 'DETECTED',requested_value jsonb,decided_by uuid REFERENCES users(id),decided_at timestamptz,created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS holidays(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),batch_id uuid REFERENCES batches(id),day date NOT NULL,name text NOT NULL,UNIQUE(batch_id,day));
CREATE TABLE IF NOT EXISTS leave_requests(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),intern_id uuid REFERENCES intern_profiles(id),from_date date,to_date date,reason text,status text DEFAULT 'REQUESTED',decided_by uuid REFERENCES users(id),decision_reason text,created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS daily_reports(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),intern_id uuid REFERENCES intern_profiles(id),day date NOT NULL,planned_tasks text,completed_tasks text,pending_blockers text,proof_links jsonb DEFAULT '[]',morning_at timestamptz,evening_at timestamptz,UNIQUE(intern_id,day));
CREATE TABLE IF NOT EXISTS weekly_tasks(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),batch_id uuid REFERENCES batches(id),domain_id uuid REFERENCES domains(id),group_id uuid REFERENCES groups(id),title text NOT NULL,description text,expected_output text,submission_types jsonb DEFAULT '[]',resources text,release_at timestamptz,due_at timestamptz,marks numeric,rubric_id uuid REFERENCES rubrics(id),status text DEFAULT 'SCHEDULED',resubmission_allowed boolean DEFAULT true);
CREATE TABLE IF NOT EXISTS task_submissions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),task_id uuid REFERENCES weekly_tasks(id),intern_id uuid REFERENCES intern_profiles(id),content jsonb NOT NULL,status text DEFAULT 'SUBMITTED',submitted_at timestamptz DEFAULT now(),is_late boolean DEFAULT false,attempt int DEFAULT 1);
CREATE TABLE IF NOT EXISTS task_evaluations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),submission_id uuid REFERENCES task_submissions(id),mentor_id uuid REFERENCES mentors(id),marks numeric,feedback text,status text DEFAULT 'APPROVED',created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS fortnight_reviews(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),group_id uuid REFERENCES groups(id),period_no int,review_date date,status text DEFAULT 'SCHEDULED',progress text,domain_review text,presentation_review text,group_marks numeric,feedback text,action_items text,next_expectations text,published_at timestamptz);
CREATE TABLE IF NOT EXISTS review_individual_marks(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),review_id uuid REFERENCES fortnight_reviews(id),intern_id uuid REFERENCES intern_profiles(id),marks numeric,contribution_note text);
CREATE TABLE IF NOT EXISTS documents(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),owner_user_id uuid REFERENCES users(id),batch_id uuid REFERENCES batches(id),group_id uuid REFERENCES groups(id),kind text,title text,file_path text,external_url text,restricted boolean DEFAULT false,created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS chat_messages(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),group_id uuid REFERENCES groups(id),sender_id uuid REFERENCES users(id),message text,attachment_id uuid REFERENCES documents(id),created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS notifications(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid REFERENCES users(id),type text,title text,body text,read_at timestamptz,created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS final_evaluations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),intern_id uuid REFERENCES intern_profiles(id),group_id uuid REFERENCES groups(id),group_marks numeric,individual_marks numeric,mentor_feedback text,recommendation text,created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS completion_approvals(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),intern_id uuid REFERENCES intern_profiles(id),status text NOT NULL,reason text,approved_by uuid REFERENCES users(id),approved_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS exit_records(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),intern_id uuid REFERENCES intern_profiles(id),type text NOT NULL,exit_date date,reason text,approved_by uuid REFERENCES users(id),created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS certificates(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),intern_id uuid REFERENCES intern_profiles(id),mode text,status text DEFAULT 'NOT_DECIDED',certificate_id text UNIQUE,issue_date date,file_path text,domain_snapshot text,date_snapshot text,created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS college_completion_reports(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),intern_id uuid REFERENCES intern_profiles(id),allotment_reference text,attendance_percent numeric,marks_summary jsonb,mentor_remarks text,status text DEFAULT 'DRAFT',file_path text,created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS audit_logs(id bigserial PRIMARY KEY,actor_id uuid REFERENCES users(id),action text NOT NULL,entity_type text,entity_id text,before_data jsonb,after_data jsonb,ip text,created_at timestamptz DEFAULT now());
CREATE INDEX IF NOT EXISTS idx_audit_entity ON audit_logs(entity_type,entity_id); CREATE INDEX IF NOT EXISTS idx_attendance_day ON attendance_daily(day); CREATE INDEX IF NOT EXISTS idx_notifications_user ON notifications(user_id,created_at DESC);

-- Assessment scoring rubric extension
ALTER TABLE assessment_sections ADD COLUMN IF NOT EXISTS rubric_id uuid REFERENCES rubrics(id);
ALTER TABLE assessment_answers ADD COLUMN IF NOT EXISTS rubric_scores jsonb DEFAULT '[]';
ALTER TABLE assessment_answers ADD COLUMN IF NOT EXISTS evaluated_at timestamptz;

-- Camera attendance verification evidence
ALTER TABLE attendance_events ADD COLUMN IF NOT EXISTS liveness_score numeric;
ALTER TABLE attendance_events ADD COLUMN IF NOT EXISTS challenge_type text;
ALTER TABLE attendance_events ADD COLUMN IF NOT EXISTS challenge_pass boolean;
ALTER TABLE attendance_events ADD COLUMN IF NOT EXISTS capture_path text;

-- Leave policy configuration
ALTER TABLE batches ADD COLUMN IF NOT EXISTS leave_limit_days int DEFAULT 3;
ALTER TABLE leave_requests ADD COLUMN IF NOT EXISTS requested_days int DEFAULT 0;
ALTER TABLE leave_requests ADD COLUMN IF NOT EXISTS decided_at timestamptz;
